# region: sift
def sift(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: shape
def shape(xs):
    return [v for v in xs if v % 2 == 0]

# region: digest
def digest(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: fold
def fold(summary, bar=4):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n // bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return fold(digest(shape(sift(raw))))

